document.addEventListener("DOMContentLoaded",function(){var e=document.querySelector(".header__burger"),t=document.querySelector(".mobile-nav");e&&t&&e.addEventListener("click",function(){e.classList.toggle("active"),t.classList.toggle("active")});var n=document.getElementById("languageToggle"),c=document.getElementById("languageText");if(n&&c){var o=function(){c.textContent="RU"===c.textContent.trim()?"EN":"RU"};n.addEventListener("click",o),n.addEventListener("keydown",function(e){"Enter"!==e.key&&" "!==e.key||(e.preventDefault(),o())})}var r=document.querySelector(".banner-blog__payment-content"),l=document.querySelector(".custom-scrollbar-thumb"),a=document.querySelector(".custom-scrollbar-track");r&&l&&a&&r.addEventListener("scroll",function(){var e=r.scrollHeight,t=r.clientHeight,n=r.scrollTop,c=e-t;if(c>0){var o=(a.clientHeight-l.clientHeight)*(n/c);l.style.top=o+"px"}},{passive:!0})});